import * as app from "./experience";
import * as ui from "./platform.dealui-pack";

// @ui-root
export view RentalShortlist(state: app.State): View {
    ui.Column() {
        ui.Hero(value: "Boom stand rental shortlist")
        ui.Card() {
            ui.Text(value: "Requirement: Boom stand")
            ui.Text(value: "Adjustable boom with clip adapter")
            ui.Text(value: "Quantity")
            ui.IntText(value: state.quantity)
            ui.Text(value: "Total budget: €10.00 for the requested quantity")
            ui.Text(value: "Period start")
            ui.Text(value: state.periodStart)
            ui.Text(value: "Period end")
            ui.Text(value: state.periodEnd)
            When(!state.loading && !state.staging && state.error === "") {
                ui.Button(text: "Load options", onClick: action app.Load {}, accessibilityLabel: "Load qualifying rental options")
            }
        }
        When(state.loading) {
            ui.Progress(label: "Loading rental options")
        } Else {
            When(state.error !== "") {
                ui.Failure(text: state.error, onRetry: action app.Load {}, accessibilityLabel: "Load options again")
            } Else {
                When(state.loaded) {
                    When(state.empty) {
                        ui.Text(value: "No options match boom and stand with sufficient availability within the total budget.")
                    } Else {
                        ui.Section(title: "Qualifying options", summary: "Prices are totals for the requested quantity and period.") {
                            ForEach(state.items, item: app.Item, key: item.id) {
                                ui.Option(value: item.id, title: item.title, detail: item.detail, price: item.price, meta: "Total price for requested quantity", enabled: item.enabled, selected: item.selected, accessibilityLabel: item.title, onSelect: action app.Pick { value: payload })
                            }
                        }
                    }
                } Else {
                    ui.Text(value: "Choose Load options to read the catalogue. No options have been loaded yet.")
                }
            }
        }
        When(state.hasSelection && !state.loading && state.error === "") {
            ui.Card() {
                ui.Text(value: "Selected for review")
                ui.Text(value: state.selectedTitle)
                ui.Text(value: state.selectedPrice)
                ui.Text(value: "Preparation stages this selection for native review only; it does not reserve equipment.")
                When(state.staging) {
                    ui.Progress(label: "Preparing for native review")
                } Else {
                    When(state.prepared) {
                        ui.Notice(text: "Prepared for native review", tone: "info")
                    } Else {
                        When(state.stageError !== "") {
                            ui.Failure(text: state.stageError, onRetry: action app.Prepare {}, accessibilityLabel: "Retry preparing the selected option for review")
                        } Else {
                            ui.Button(text: "Prepare for review", onClick: action app.Prepare {}, accessibilityLabel: "Prepare the selected rental option for native review")
                        }
                    }
                }
            }
        }
    }
}
